ext('c12_phy_ch4',[
C("🧭","चुंबकीय क्षेत्र में आवेश की गति",["गति के लंबवत बल","बल से चाल नहीं बदलती","वृत्ताकार या कुंडलाकार पथ","लॉरेंज़ बल"],"जब कोई आवेश चुंबकीय क्षेत्र में गति करता है, तो उस पर लॉरेंज़ बल लगता है। यह बल आवेश की गति की दिशा के लंबवत होता है, इसलिए यह चाल नहीं बदलता, केवल दिशा बदलता है। अगर गति क्षेत्र के लंबवत हो तो पथ वृत्ताकार बनता है।"),
C("📐","फ़्लेमिंग का बायाँ हाथ नियम",["अँगूठा: बल","तर्जनी: चुंबकीय क्षेत्र","मध्यमा: धारा","तीनों परस्पर लंबवत"],"चुंबकीय क्षेत्र में रखे धारावाही तार पर बल की दिशा जानने के लिए फ़्लेमिंग का बायाँ हाथ नियम काम आता है। बाएँ हाथ का अँगूठा, तर्जनी और मध्यमा परस्पर लंबवत रखिए। तर्जनी क्षेत्र की दिशा, मध्यमा धारा की दिशा और अँगूठा बल की दिशा बताता है।"),
C("🔄","साइक्लोट्रॉन",["आवेशित कणों को त्वरित करता","चुंबकीय और विद्युत क्षेत्र","कण सर्पिल पथ में","दोलन आवृत्ति स्थिर"],"साइक्लोट्रॉन एक ऐसी मशीन है जो आवेशित कणों की ऊर्जा बढ़ाती है। इसमें चुंबकीय क्षेत्र कणों को वृत्ताकार पथ में घुमाता है, और बीच के खाली स्थान में विद्युत क्षेत्र उन्हें हर चक्कर में थोड़ी और ऊर्जा देता है। कण बाहर की ओर सर्पिल पथ में बढ़ते जाते हैं।"),
C("⚙️","चल कुंडली धारामापी",["धारा मापने का यंत्र","कुंडली पर बल-आघूर्ण","स्प्रिंग प्रत्यानयन","शंट से ऐमीटर","श्रेणी प्रतिरोध से वोल्टमीटर"],"चल कुंडली धारामापी में चुंबकीय क्षेत्र में रखी कुंडली पर धारा बहने पर बल-आघूर्ण लगता है, जिससे वह घूमती है। स्प्रिंग इसे वापस खींचता है, इसलिए घूर्णन कोण धारा के अनुपात में होता है। इसके समांतर में छोटा प्रतिरोध लगाने पर यह ऐमीटर बनता है और श्रेणी में बड़ा प्रतिरोध लगाने पर वोल्टमीटर।"),
],5)
ext('c12_phy_ch5',[
C("🧲","छड़ चुंबक के गुण",["उत्तरी और दक्षिणी ध्रुव","समान ध्रुव प्रतिकर्षित","असमान ध्रुव आकर्षित","ध्रुव अलग नहीं किए जा सकते"],"छड़ चुंबक के दो सिरों पर दो ध्रुव होते हैं, उत्तरी और दक्षिणी। समान ध्रुव एक-दूसरे को दूर धकेलते हैं और असमान ध्रुव खींचते हैं। चुंबक को बीच से काटने पर भी हर टुकड़ा अपना उत्तरी और दक्षिणी ध्रुव बना लेता है। चुंबकीय एकल ध्रुव आज तक नहीं मिला।"),
C("🌍","पृथ्वी का चुंबकत्व",["पृथ्वी एक विशाल चुंबक","दिक्पात कोण","नमन कोण","क्षैतिज घटक"],"पृथ्वी एक बहुत बड़े चुंबक की तरह व्यवहार करती है। किसी स्थान पर चुंबकीय देशांतर और भौगोलिक देशांतर के बीच का कोण दिक्पात कहलाता है। चुंबकीय सुई जिस कोण से क्षैतिज से झुकती है उसे नमन कोण कहते हैं। पृथ्वी के क्षेत्र का क्षैतिज घटक दिशा-सूचक यंत्र के काम आता है।"),
C("🌡️","क्यूरी ताप",["लौह चुंबकीय पदार्थ","ताप बढ़ने पर चुंबकत्व घटता","क्यूरी ताप के ऊपर अनुचुंबकीय","फिर चुंबक नहीं रहता"],"लौह चुंबकीय पदार्थ, जैसे लोहा, निकल और कोबाल्ट, बहुत शक्तिशाली चुंबकीय गुण दिखाते हैं। जब इन्हें गर्म किया जाता है तो एक निश्चित ताप पर उनका चुंबकत्व समाप्त हो जाता है और वे अनुचुंबकीय बन जाते हैं। इस ताप को क्यूरी ताप कहते हैं।"),
C("💡","विद्युत चुंबक के उपयोग",["नरम लोहे की क्रोड","घंटी, क्रेन, रिले","धारा बंद तो चुंबकत्व समाप्त","स्थायी चुंबक से भिन्न"],"विद्युत चुंबक नरम लोहे की क्रोड पर लिपटे तार में धारा बहाकर बनाया जाता है। धारा बंद करते ही इसका चुंबकत्व लगभग समाप्त हो जाता है। इसलिए इसका उपयोग घंटी, क्रेन और रिले जैसी जगहों पर होता है। स्थायी चुंबक इस्पात से बनते हैं जो अपना चुंबकत्व बनाए रखते हैं।"),
],5)
ext('c12_phy_ch6',[
C("🔄","लेंज़ का नियम और ऊर्जा संरक्षण",["प्रेरित धारा की दिशा","कारण का विरोध करती","ऊर्जा संरक्षण का परिणाम","काम करके ही धारा बनती"],"लेंज़ का नियम कहता है कि प्रेरित धारा की दिशा ऐसी होती है कि वह उस कारण का विरोध करे जिससे वह उत्पन्न हुई है। यह ऊर्जा संरक्षण का नियम है। अगर धारा विरोध करने के बजाय सहायता करती, तो बिना काम किए ऊर्जा मिलने लगती, जो असंभव है।"),
C("🌀","भँवर धाराओं के उपयोग",["चुंबकीय क्षेत्र बदलने से धाराएँ","ब्रेक में उपयोग","प्रेरण भट्ठी","विद्युत मीटर में अवमंदन"],"जब किसी धात्विक वस्तु में चुंबकीय फ़्लक्स बदलता है, तो उसमें गोलाकार धाराएँ बन जाती हैं जिन्हें भँवर धाराएँ कहते हैं। इनका उपयोग रेलगाड़ी के ब्रेक, प्रेरण भट्ठी और मीटर में कंपन रोकने के लिए होता है। पर ट्रांसफ़ॉर्मर में ये ऊर्जा की हानि करती हैं।"),
C("🔌","स्व-प्रेरण और अन्योन्य प्रेरण",["स्व-प्रेरण: अपनी ही कुंडली में","अन्योन्य प्रेरण: पास की कुंडली में","प्रेरकत्व की इकाई हेनरी","ट्रांसफ़ॉर्मर का आधार"],"जब किसी कुंडली में बहने वाली धारा बदलती है, तो उसी कुंडली में एक विद्युत वाहक बल प्रेरित होता है, इसे स्व-प्रेरण कहते हैं। जब पास की दूसरी कुंडली में बल प्रेरित हो, तो वह अन्योन्य प्रेरण है। प्रेरकत्व की इकाई हेनरी है। ट्रांसफ़ॉर्मर अन्योन्य प्रेरण के सिद्धांत पर चलता है।"),
C("🏭","ए.सी. जनित्र की रचना",["आर्मेचर या कुंडली","चुंबकीय क्षेत्र","स्लिप रिंग और ब्रश","घूमने से प्रत्यावर्ती वाहक बल"],"ए.सी. जनित्र में चुंबकीय क्षेत्र के बीच एक कुंडली घुमाई जाती है। घूमने के साथ कुंडली से गुज़रने वाला चुंबकीय फ़्लक्स बदलता है और उसमें प्रत्यावर्ती विद्युत वाहक बल पैदा होता है। स्लिप रिंग और ब्रश के द्वारा यह बल बाहरी परिपथ तक पहुँचता है।"),
],5)
ext('c12_phy_ch7',[
C("📉","आर.एम.एस. मान",["शिखर मान से कम","शिखर मान भाग √2","वास्तविक ऊष्मीय प्रभाव","भारतीय घरों की 220 वोल्ट"],"प्रत्यावर्ती धारा का मान हर क्षण बदलता रहता है, इसलिए उसका प्रभावी मान निकाला जाता है, जिसे वर्ग माध्य मूल मान कहते हैं। यह शिखर मान को दो के वर्गमूल से भाग देने पर मिलता है। हमारे घरों में दो सौ बीस वोल्ट आर.एम.एस. मान है, जिसका शिखर मान लगभग तीन सौ ग्यारह वोल्ट होता है।"),
C("🔗","एल.सी.आर. परिपथ की प्रतिबाधा",["प्रतिरोध, प्रेरक अभिक्रिया, धारितीय अभिक्रिया","प्रतिबाधा का सूत्र","कला कोण","अनुनाद की स्थिति"],"श्रेणी एल.सी.आर. परिपथ में कुल रोध को प्रतिबाधा कहते हैं। यह प्रतिरोध और दोनों अभिक्रियाओं के अंतर से निकलती है। जब प्रेरक अभिक्रिया और धारितीय अभिक्रिया बराबर हो जाएँ, तो परिपथ अनुनाद में आ जाता है और प्रतिबाधा सबसे कम होकर केवल प्रतिरोध के बराबर रह जाती है।"),
C("📻","अनुनाद का उपयोग",["रेडियो ट्यूनिंग","सही आवृत्ति पर चुनाव","अधिकतम धारा","गुणता गुणांक"],"रेडियो को किसी स्टेशन पर लगाते समय हम परिपथ की धारिता बदलते हैं ताकि उसकी अनुनादी आवृत्ति स्टेशन की आवृत्ति के बराबर हो जाए। तब उस आवृत्ति पर धारा सबसे ज़्यादा बहती है और वही स्टेशन सुनाई देता है। गुणता गुणांक अनुनाद की तीक्ष्णता बताता है।"),
C("⚙️","ट्रांसफ़ॉर्मर की कार्यप्रणाली",["प्राथमिक और द्वितीयक कुंडली","अन्योन्य प्रेरण का सिद्धांत","चरण-ऊपर और चरण-नीचे","ऊर्जा की हानि के कारण"],"ट्रांसफ़ॉर्मर में लोहे की क्रोड पर दो कुंडलियाँ लिपटी होती हैं। प्राथमिक में प्रत्यावर्ती वोल्टेज देने पर द्वितीयक में अन्योन्य प्रेरण से वोल्टेज बनता है। चरण-ऊपर में फेरे ज़्यादा होते हैं और चरण-नीचे में कम। ऊर्जा की हानि ताँबे के तारों की गर्मी, भँवर धाराओं और फ़्लक्स रिसाव से होती है।"),
],5)
ext('c12_phy_ch8',[
C("📡","वैद्युत चुंबकीय तरंगों का वेग",["निर्वात में समान वेग","तीन गुणा दस की घात आठ मीटर प्रति सेकंड","प्रकाश भी वैद्युत चुंबकीय तरंग","माध्यम में वेग कम"],"सभी वैद्युत चुंबकीय तरंगें निर्वात में एक ही वेग से चलती हैं, जो लगभग तीन सौ करोड़ मीटर प्रति सेकंड के बराबर है। प्रकाश भी एक वैद्युत चुंबकीय तरंग है। किसी माध्यम में इनका वेग निर्वात की तुलना में कम हो जाता है।"),
C("🌈","स्पेक्ट्रम के प्रमुख उपयोग",["रेडियो तरंगें: संचार","सूक्ष्म तरंगें: ओवन, रडार","अवरक्त: रिमोट, गर्मी","एक्स-किरणें: चिकित्सा"],"वैद्युत चुंबकीय स्पेक्ट्रम में तरंगें आवृत्ति के क्रम में रखी जाती हैं। रेडियो तरंगें संचार में काम आती हैं और सूक्ष्म तरंगें ओवन और रडार में। अवरक्त किरणें रिमोट कंट्रोल में, पराबैंगनी किरणें जीवाणु नाश में और एक्स-किरणें चिकित्सा में हड्डियों की जाँच में काम आती हैं।"),
C("☀️","पराबैंगनी का प्रभाव",["सूर्य से आती हैं","त्वचा के लिए हानिकारक","ओज़ोन परत सोखती है","कीटाणुनाशक के रूप में उपयोग"],"सूर्य से पराबैंगनी किरणें भी आती हैं। ज़्यादा मात्रा में ये त्वचा को जला सकती हैं और आँखों व त्वचा के कैंसर का कारण बन सकती हैं। वायुमंडल की ओज़ोन परत इनका बड़ा भाग सोख लेती है। पराबैंगनी किरणों का उपयोग पानी साफ़ करने और अस्पतालों में कीटाणु मारने में भी होता है।"),
C("🧮","विस्थापन धारा का महत्त्व",["परिवर्ती विद्युत क्षेत्र से चुंबकीय क्षेत्र","मैक्सवेल की देन","ऐम्पियर के नियम का संशोधन","तरंगों की भविष्यवाणी"],"मैक्सवेल ने बताया कि बदलता हुआ विद्युत क्षेत्र भी चुंबकीय क्षेत्र पैदा करता है। इसी को विस्थापन धारा कहा गया। इस विचार से उन्होंने ऐम्पियर के नियम को संशोधित किया और भविष्यवाणी की कि वैद्युत चुंबकीय तरंगें अस्तित्व में होंगी। बाद में हर्ट्ज़ ने प्रयोग से इन्हें खोजा।"),
],5)
ext('c12_phy_ch9',[
C("🔍","पूर्ण आंतरिक परावर्तन के उपयोग",["प्रकाशीय तंतु","हीरे की चमक","मृगतृष्णा","प्रिज़्म में परावर्तन"],"जब प्रकाश सघन माध्यम से विरल माध्यम में क्रांतिक कोण से अधिक कोण पर जाता है, तो पूरी तरह परावर्तित हो जाता है। प्रकाशीय तंतु में यही सिद्धांत लागू होता है और संचार में काम आता है। हीरे की चमक और मृगतृष्णा भी इसी घटना से बनती है।"),
C("🔭","खगोलीय दूरदर्शी",["अभिदृश्यक: बड़ी द्वारक","नेत्रिका: छोटी फ़ोकस दूरी","दूर की वस्तु का प्रतिबिंब","आवर्धन क्षमता"],"खगोलीय दूरदर्शी दूर की वस्तुओं, जैसे तारों और ग्रहों को देखने के काम आता है। इसमें दो लेंस होते हैं, अभिदृश्यक और नेत्रिका। अभिदृश्यक की द्वारक बड़ी और फ़ोकस दूरी ज़्यादा होती है ताकि ज़्यादा प्रकाश इकट्ठा हो सके। नेत्रिका की फ़ोकस दूरी कम होती है और वह प्रतिबिंब को बड़ा करके दिखाती है।"),
C("🔬","संयुक्त सूक्ष्मदर्शी",["दो लेंस की व्यवस्था","छोटी वस्तु को बड़ा दिखाना","अभिदृश्यक वस्तु के पास","नेत्रिका से अंतिम प्रतिबिंब"],"संयुक्त सूक्ष्मदर्शी बहुत छोटी वस्तुओं को बड़ा करके दिखाता है। इसमें अभिदृश्यक की फ़ोकस दूरी बहुत कम होती है और वस्तु उसके पास रखी जाती है। वह एक बड़ा और उलटा प्रतिबिंब बनाता है, जिसे नेत्रिका और बड़ा करके हमारी आँख को दिखाती है।"),
C("👓","चश्मे से दृष्टि दोष का सुधार",["निकट दृष्टि: अवतल लेंस","दीर्घ दृष्टि: उत्तल लेंस","जरा दृष्टि: द्विफोकसी","अबिंदुकता: बेलनाकार लेंस"],"निकट दृष्टि दोष में दूर की वस्तु साफ़ नहीं दिखती, इसे अवतल लेंस से ठीक करते हैं। दीर्घ दृष्टि में पास की वस्तु साफ़ नहीं दिखती, इसे उत्तल लेंस से सुधारते हैं। उम्र बढ़ने पर जरा दृष्टि के लिए द्विफोकसी लेंस लगता है और अबिंदुकता के लिए बेलनाकार लेंस।"),
],5)
